-- Cuba de gelato é sempre 1 unidade (1 etiqueta = 1 cuba), nunca caixa de N.
-- Trava no ponto único: a coluna de etiquetas_qr que TODOS os fluxos de
-- entrada/contagem leem (bipar_etiqueta, bipar_lote_scanner, Scanner, EntradaBip).
-- Assim, qualquer rebipagem de cuba soma 1, independente de como a etiqueta nasceu.
CREATE OR REPLACE FUNCTION public.enforce_cuba_unidade_etiqueta()
RETURNS trigger
LANGUAGE plpgsql
SET search_path TO 'public'
AS $function$
BEGIN
  IF EXISTS (
    SELECT 1 FROM public.produtos_master pm
    WHERE pm.id = NEW.produto_master_id
      AND lower(pm.nome) ~ '\mcuba\M'
  ) THEN
    NEW.quantidade_interna    := 1;
    NEW.tipo_embalagem        := 'unidade';
    NEW.embalagem_nome        := 'un';
    -- mantém capacidade=1; permite 0 (consumida) mas nunca > 1
    NEW.quantidade_disponivel := LEAST(COALESCE(NEW.quantidade_disponivel, 1), 1);
  END IF;
  RETURN NEW;
END;
$function$;

DROP TRIGGER IF EXISTS trg_enforce_cuba_unidade ON public.etiquetas_qr;
CREATE TRIGGER trg_enforce_cuba_unidade
  BEFORE INSERT OR UPDATE ON public.etiquetas_qr
  FOR EACH ROW
  EXECUTE FUNCTION public.enforce_cuba_unidade_etiqueta();

-- Produtos unitários (cuba de gelato e naked/tortas) contam sempre 1:1.
-- Generaliza a trava antes específica de "cuba" para também cobrir "naked".
-- Mesmo princípio: força na coluna de etiquetas_qr que todos os fluxos de
-- entrada/contagem leem, então qualquer bipagem soma 1 (nunca caixa de N).
CREATE OR REPLACE FUNCTION public.enforce_produto_unitario_etiqueta()
RETURNS trigger
LANGUAGE plpgsql
SET search_path TO 'public'
AS $function$
BEGIN
  IF EXISTS (
    SELECT 1 FROM public.produtos_master pm
    WHERE pm.id = NEW.produto_master_id
      AND lower(pm.nome) ~ '\m(cuba|naked)\M'
  ) THEN
    NEW.quantidade_interna    := 1;
    NEW.tipo_embalagem        := 'unidade';
    NEW.embalagem_nome        := 'un';
    NEW.quantidade_disponivel := LEAST(COALESCE(NEW.quantidade_disponivel, 1), 1);
  END IF;
  RETURN NEW;
END;
$function$;

DROP TRIGGER IF EXISTS trg_enforce_cuba_unidade ON public.etiquetas_qr;
DROP TRIGGER IF EXISTS trg_enforce_produto_unitario ON public.etiquetas_qr;
CREATE TRIGGER trg_enforce_produto_unitario
  BEFORE INSERT OR UPDATE ON public.etiquetas_qr
  FOR EACH ROW
  EXECUTE FUNCTION public.enforce_produto_unitario_etiqueta();

DROP FUNCTION IF EXISTS public.enforce_cuba_unidade_etiqueta();

CREATE TABLE IF NOT EXISTS bkp_fix_naked_fabrica_20260604_etiquetas AS
  SELECT eq.* FROM etiquetas_qr eq JOIN produtos_master pm ON pm.id=eq.produto_master_id
  WHERE lower(unaccent(pm.nome)) ~ '\mnaked\M' AND eq.loja_atual_id=1;
CREATE TABLE IF NOT EXISTS bkp_fix_naked_fabrica_20260604_estoque AS
  SELECT e.* FROM estoque e JOIN produtos_master pm ON pm.id=e.produto_master_id
  WHERE lower(unaccent(pm.nome)) ~ '\mnaked\M' AND e.loja_id=1;
CREATE TABLE IF NOT EXISTS bkp_fix_naked_fabrica_20260604_estoque_lotes AS
  SELECT el.* FROM estoque_lotes el JOIN produtos_master pm ON pm.id=el.produto_id
  WHERE lower(unaccent(pm.nome)) ~ '\mnaked\M' AND el.loja_id=1;
SELECT
  (SELECT count(*) FROM bkp_fix_naked_fabrica_20260604_etiquetas) AS bkp_etiquetas,
  (SELECT count(*) FROM bkp_fix_naked_fabrica_20260604_estoque) AS bkp_estoque,
  (SELECT count(*) FROM bkp_fix_naked_fabrica_20260604_estoque_lotes) AS bkp_estoque_lotes;

